				commRule = Dpr.EncountTools.CommRule.Mix;
				break;
			case BattleModeID.Multi:
				commRule = Dpr.EncountTools.CommRule.Multi;
				break;
			default:
				commRule = Dpr.EncountTools.CommRule.Single;
				break;
