			BattleMatchingPlayerData playerData = playerDataList[i];
			mystatusList[i] = new MYSTATUS_COMM();
			mystatusList[i].name = playerData.name;
			mystatusList[i].sex = playerData.sexId == 0;
			mystatusList[i].fashion = (byte)playerData.avatarId;
			mystatusList[i].id = playerData.id;
			mystatusList[i].lang = (byte)playerData.language;
			mystatusList[i].body_type = (byte)playerData.colorId;
			mystatusList[i].hat = 0;
			mystatusList[i].shoes = 0;

			partyList[i] = new Pml.PokeParty();
			PokemonParam[] battlePokemon = playerData.battlePokemon;
			for (int j = 0; j < battlePokemon.Length; j++)
			{
				PokemonParam pokemonParam = battlePokemon[j];
				if (pokemonParam == null)
					continue;

				if (playerData.stationIndex != BattleMatchingWork.stationIndex)
				{
					if (pokemonParam.HaveNickName())
