					parentName = Dpr.SubContents.Utils.CheckNGTrainerName(ref parentName, (Dpr.Message.MessageEnumData.MsgLangId)pokemonParam.GetLangId(), (int)pokemonParam.GetCassetteVersion());
					pokemonParam.SetParentName(parentName);
