			capsuleDataList[i] = playerDataList[i].capsule;
		}

		PokemonNum pokemonNum = BattleMatchingWork.pokemonNum;
		Dpr.Regulation.Data regulation = new Dpr.Regulation.Data((byte)BattleMatchingWork.GetPokemonNumMin(pokemonNum), (byte)BattleMatchingWork.GetPokemonNumMax(pokemonNum),
