		byte commPos = (byte)commPosList[BattleMatchingWork.GetIndexMine()];
		string winBgm = BattleMatchingWork.isColiseum ? "BA101" : null;
		Dpr.Battle.Logic.BATTLE_SETUP_PARAM bsp = PlayerWork.battleSetupParam;
		IlcaNetSessionNetworkType networkType = BattleMatchingWork.networkType;

		int stationIndex0 = -1;
