	public void ReturnBattle() {
		BattleMatchingWork.EmitLog(string.Format("ReturnBattle : [{0}]", BattleMatchingWork.battleResult));
		_currentState = MatchingState.Initialize;
		AudioManager.Instance.SetBgmEvent(BattleMatchingWork.isColiseum ? AK.EVENTS.BA101 : AK.EVENTS.BA102, false);

		Sequencer.Start(LoadBattleMatchingUI(window =>
		{
			_battleMatchingUI = window;
			_currentState = MatchingState.Load;
			if (IsNetworkError())
			{
				BattleMatchingWork.EmitLog("NetworkError On ReturnBattle");
				FinishMatching();
				return;
			}

			Sequencer.update -= OnUpdate;
			Sequencer.update += OnUpdate;

			_battleMatchingUI.OpenResume();
			if (CheckLeavedMember())
			{
				BattleMatchingWork.EmitLog("Now Matching Player is NoActive");
				LeaveOther(BattleMatchingWork.opponentStationIndex);
				return;
			}

			ChangeState(MatchingState.Result);
		}));
	}
	public void ReturnBattleError() {
