	private uint GetColiseumBgm() {
		int index = BattleMatchingWork.GetIndex(IlcaNetSession.HostStationIndex());
		BattleMatchingPlayerData[] playerDataList = BattleMatchingWork.playerDataList;
		if (playerDataList != null && index < playerDataList.Length && playerDataList[index] != null)
		{
			switch (playerDataList[index].id % 10)
			{
				case 1: return AK.EVENTS.BA002;
				case 2: return AK.EVENTS.BA003;
				case 3: return AK.EVENTS.BA014;
				case 4: return AK.EVENTS.BA010;
				case 5: return AK.EVENTS.BA007;
				case 6: return AK.EVENTS.BA015_GIR;
				case 7: return AK.EVENTS.BA009;
				case 8: return AK.EVENTS.BA017;
				case 9: return AK.EVENTS.BA018;
			}
		}
		return AK.EVENTS.BA001;
	}
