		netData.data.avatarId = (byte)PlayerWork.playerFashion;
		netData.data.sexId = (byte)(PlayerWork.playerSex ? 0 : 1);
		netData.data.cassetVersion = (byte)PlayerWork.cassetVersion;
		netData.SendReliableData(targetStationIndex, TransportType.Station);
	}
	private void SendJoinMemberData(int index, global::Dpr.NetworkUtils.NetDataBattleMatchingJoin data) {
		BattleMatchingWork.EmitLog(string.Format("Send JoinMember Data to [{0}]", index));
		data.data.index = (byte)index;

		BattleMatchingPlayerData[] playerDataList = BattleMatchingWork.playerDataList;
		for (int i = 0; i < playerDataList.Length; i++)
		{
			if (playerDataList[i] == null || playerDataList[i].stationIndex == BattleMatchingWork.stationIndex)
				continue;

			data.SendReliableData(playerDataList[i].stationIndex, TransportType.Station);
			if (playerDataList[i].stationIndex != data.data.stationIndex)
			{
				NetDataBattleMatchingJoin memberData = new NetDataBattleMatchingJoin();
				memberData.data.stationIndex = (byte)playerDataList[i].stationIndex;
				memberData.data.index = (byte)i;
				memberData.data.id = playerDataList[i].id;
				memberData.data.language = (byte)playerDataList[i].language;
				memberData.data.colorId = (byte)playerDataList[i].colorId;
				memberData.data.avatarId = (byte)playerDataList[i].avatarId;
				memberData.data.sexId = (byte)playerDataList[i].sexId;
				memberData.SendReliableData(data.data.stationIndex, TransportType.Station);
			}
		}
	}
	public void SendLeaveData() {
		BattleMatchingWork.EmitLog("Send Leave Data to All");
		NetDataBattleMatchingLeave netData = new NetDataBattleMatchingLeave();
		int[] otherStationIndex = BattleMatchingWork.GetOtherStationIndex();
		for (int i = 0; i < otherStationIndex.Length; i++)
			netData.SendReliableData(otherStationIndex[i], TransportType.Station);

		if (!BattleMatchingWork.isColiseum && !Array.Exists(otherStationIndex, x => BattleMatchingWork.opponentStationIndex == x))
			netData.SendReliableData(BattleMatchingWork.opponentStationIndex, TransportType.Station);
	}
	public void SendReadyData() {
		int hostStationIndex = BattleMatchingWork.hostStationIndex;
		if (hostStationIndex == BattleMatchingWork.stationIndex)
		{
			BattleMatchingWork.SetReadyPlayer(BattleMatchingWork.stationIndex);
			if (BattleMatchingWork.GetReadyAllPlayers())
				SendStateData();
		}
		else
		{
			BattleMatchingWork.EmitLog(string.Format("Send Ready Data to [{0}]", hostStationIndex));
			new NetDataBattleMatchingReady().SendReliableData(hostStationIndex, TransportType.Station);
		}
	}
	public void SendStateData() {
		if (_currentState == MatchingState.GoBattle)
			return;

		MatchingState state = NextState();
		NetDataBattleMatchingState netData = new NetDataBattleMatchingState();
		netData.data.index = (byte)state;

		BattleMatchingPlayerData[] playerDataList = BattleMatchingWork.playerDataList;
		for (int i = 0; i < playerDataList.Length; i++)
		{
			if (playerDataList[i] != null && playerDataList[i].stationIndex != BattleMatchingWork.stationIndex)
			{
				BattleMatchingWork.EmitLog(string.Format("Send State Data to [{0}]", playerDataList[i].stationIndex));
				netData.SendReliableData(playerDataList[i].stationIndex, TransportType.Station);
			}
		}
		ChangeState(state);
	}
