	public void SendSelectPokemonData() {
		PokemonParam[] pokemonParams;
		CapsuleData[] capsuleDatas;
		int pokemonNum;
		if (_currentState == MatchingState.SelectPokemon)
		{
			pokemonParams = new PokemonParam[6];
			capsuleDatas = new CapsuleData[6];
			foreach (CapsuleData capsuleData in capsuleDatas)
				capsuleData.Clear();

			pokemonNum = BattleMatchingWork.orderIndexList.Length;
			for (int i = 0; i < pokemonNum; i++)
			{
				int orderIndex = BattleMatchingWork.orderIndexList[i];
				pokemonParams[i] = BattleMatchingWork.pokemonParams[orderIndex];

				CAPSULEDATA_COMM capsuleComm = new CAPSULEDATA_COMM();
				if (BattleMatchingWork.battleTeamIndex < 0)
				{
					capsuleComm.SetupFromPlayerWork(orderIndex);
				}
				else
				{
					int tray = BoxWork.GetTeamPokeBoxTray(BattleMatchingWork.battleTeamIndex, orderIndex);
					int pos = BoxWork.GetTeamPokeBoxPos(BattleMatchingWork.battleTeamIndex, orderIndex);
					capsuleComm.SetupFromPlayerWork(tray, pos);
				}
				capsuleDatas[i] = capsuleComm.capsule;
			}
		}
		else if (_currentState == MatchingState.SelectBattleTeam)
		{
			pokemonParams = BattleMatchingWork.pokemonParams;
			pokemonNum = 0;
			for (int i = 0; i < pokemonParams.Length; i++)
			{
				if (pokemonParams[i] != null)
					pokemonNum++;
			}
			capsuleDatas = null;
		}
		else
		{
			capsuleDatas = null;
			pokemonParams = null;
			pokemonNum = 0;
		}

		int[] otherStationIndex = BattleMatchingWork.GetOtherStationIndex();
		for (int i = 0; i < pokemonParams.Length; i++)
		{
			if (pokemonParams[i] == null)
				continue;

			NetDataBattleMatchingSelectPokemon netData = new NetDataBattleMatchingSelectPokemon();
			netData.data.index = (byte)i;
			netData.data.num = (byte)pokemonNum;
			netData.data.pokeData = pokemonParams[i].GetCoreData();
			if (capsuleDatas != null && i < capsuleDatas.Length)
			{
				if (capsuleDatas[i].AffixSealDatas == null)
					continue;

				netData.data.sealData = new SealParam[BallDecoWork.AffixSealMaxCount];
				for (int j = 0; j < BallDecoWork.AffixSealMaxCount; j++)
				{
					netData.data.sealData[j] = new SealParam();
					netData.data.sealData[j].sealID = (byte)capsuleDatas[i].AffixSealDatas[j].SealId;
					netData.data.sealData[j].sealPosX = capsuleDatas[i].AffixSealDatas[j].PositionX;
					netData.data.sealData[j].sealPosY = capsuleDatas[i].AffixSealDatas[j].PositionY;
					netData.data.sealData[j].sealPosZ = capsuleDatas[i].AffixSealDatas[j].PositionZ;
				}
				netData.data.is3DEditMode = (byte)(capsuleDatas[i].Is3DEditMode ? 0 : 1);
				netData.data.isAppliedTemplate = (byte)(capsuleDatas[i].IsAppliedTemplate ? 0 : 1);
				netData.data.affixSealCount = capsuleDatas[i].AffixSealCount;
				netData.data.attachPokemonId = capsuleDatas[i].AttachPokemonId;
				netData.data.attachPersonalRnd = capsuleDatas[i].AttachPersonalRnd;
			}

			for (int j = 0; j < otherStationIndex.Length; j++)
				netData.SendReliableData(otherStationIndex[j], TransportType.Station);
		}
	}
