	public void ReceiveData(global::Dpr.NetworkUtils.INetData netData) {
		if (_currentState == MatchingState.None || _currentState == MatchingState.Initialize)
		{
			BattleMatchingWork.EmitLog(string.Format("Enqueue Receive Data : [{0}]", netData));
			_loadingRecieveData.Enqueue(netData.Clone);
			return;
		}

		BattleMatchingWork.EmitLog(string.Format("Receive Data : [{0}]", netData));
		if (NetDataBattleMatchingJoin.DataID == netData.GetDataID)
		{
			ReceiveJoinData((NetDataBattleMatchingJoin)netData);
		}
		else if (NetDataBattleMatchingLeave.DataID == netData.GetDataID)
		{
			ReceiveLeaveData((NetDataBattleMatchingLeave)netData);
		}
		else if (NetDataBattleMatchingReady.DataID == netData.GetDataID)
		{
			ReceiveReadyData((NetDataBattleMatchingReady)netData);
		}
		else if (NetDataBattleMatchingState.DataID == netData.GetDataID)
		{
			ReceiveStateData((NetDataBattleMatchingState)netData);
		}
		else if (NetDataBattleMatchingSelectTeam.DataID == netData.GetDataID)
		{
			ReceiveSelectTeamData((NetDataBattleMatchingSelectTeam)netData);
		}
		else if (NetDataBattleMatchingDecideTeam.DataID == netData.GetDataID)
		{
			ReceiveDecideTeamData((NetDataBattleMatchingDecideTeam)netData);
		}
		else if (NetDataBattleMatchingSelectRuleMember.DataID == netData.GetDataID)
		{
			ReceiveSelectRuleMemberData((NetDataBattleMatchingSelectRuleMember)netData);
		}
		else if (NetDataBattleMatchingDecideRuleMember.DataID == netData.GetDataID)
		{
			ReceiveDecideRuleMemberData((NetDataBattleMatchingDecideRuleMember)netData);
		}
		else if (NetDataBattleMatchingRule.DataID == netData.GetDataID)
		{
			ReceiveRuleData((NetDataBattleMatchingRule)netData);
		}
		else if (NetDataBattleMatchingSelectPokemon.DataID == netData.GetDataID)
		{
			ReceiveSelectPokemonData((NetDataBattleMatchingSelectPokemon)netData);
		}
		else if (NetDataBattleMatchingCancelPokemon.DataID == netData.GetDataID)
		{
			ReceiveCancelPokemonData((NetDataBattleMatchingCancelPokemon)netData);
		}
		else if (NetDataBattleMatchingResume.DataID == netData.GetDataID)
		{
			if (_currentState == MatchingState.Resume)
			{
				ReceiveResumeData((NetDataBattleMatchingResume)netData);
			}
			else
			{
				BattleMatchingWork.EmitLog(string.Format("Enqueue Receive Data : [{0}]", netData));
				_loadingRecieveData.Enqueue(netData.Clone);
			}
		}
		else if (NetDataBattleMatchingCountDown.DataID == netData.GetDataID)
		{
			ReceiveCountDownData((NetDataBattleMatchingCountDown)netData);
		}
		else if (NetDataTalkCancelEndData.DataID == netData.GetDataID)
		{
			ReceiveTalkCancelData((NetDataTalkCancelEndData)netData);
		}
		else if (NetDataBattleRuleCancelData.DataID == netData.GetDataID)
		{
			ReceiveTalkCancelData((NetDataBattleRuleCancelData)netData);
		}
	}
	private void ReceiveJoinData(global::Dpr.NetworkUtils.NetDataBattleMatchingJoin data) {
		int index = data.data.index;
		bool isHost = BattleMatchingWork.hostStationIndex == BattleMatchingWork.stationIndex;
		if (isHost && !BattleMatchingWork.isColiseum)
		{
			BattleMatchingPlayerData[] playerDataList = BattleMatchingWork.playerDataList;
			for (int i = 1; i < playerDataList.Length; i++)
			{
				if (playerDataList[i] == null)
				{
					index = i;
					break;
				}
			}
		}

		_recruitmentMember.JoinMember(index, data.data.stationIndex, data);
		if (isHost)
		{
			SendJoinMineData(data.FromStationIndex);
			SendJoinMemberData(index, data);
		}
	}
