	private void ReceiveSelectPokemonData(global::Dpr.NetworkUtils.NetDataBattleMatchingSelectPokemon data) {
		int stationIndex = data.FromStationIndex;
		PokemonParam pokemonParam = new PokemonParam();
		pokemonParam.Deserialize_Core(data.data.pokeData);

		BattleMatchingPlayerData[] playerDataList = BattleMatchingWork.playerDataList;
		for (int i = 0; i < playerDataList.Length; i++)
		{
			BattleMatchingPlayerData playerData = playerDataList[i];
			if (playerData == null || playerData.stationIndex != stationIndex)
				continue;

			if (_currentState == MatchingState.SelectPokemon)
			{
				if (playerData.battlePokemon == null)
					playerData.battlePokemon = new PokemonParam[6];

				if (playerData.capsule == null)
				{
					playerData.capsule = new CapsuleData[6];
					foreach (CapsuleData capsuleData in playerData.capsule)
						capsuleData.Clear();
				}

				playerData.battlePokemon[data.data.index] = pokemonParam;
				playerData.battlePokemonNum = data.data.num;
				playerData.capsule[data.data.index].AffixSealDatas = new AffixSealData[BallDecoWork.AffixSealMaxCount];
				for (int j = 0; j < BallDecoWork.AffixSealMaxCount; j++)
				{
					playerData.capsule[data.data.index].AffixSealDatas[j].SealId = data.data.sealData[j].sealID;
					playerData.capsule[data.data.index].AffixSealDatas[j].PositionX = data.data.sealData[j].sealPosX;
					playerData.capsule[data.data.index].AffixSealDatas[j].PositionY = data.data.sealData[j].sealPosY;
					playerData.capsule[data.data.index].AffixSealDatas[j].PositionZ = data.data.sealData[j].sealPosZ;
				}
				playerData.capsule[data.data.index].Is3DEditMode = data.data.is3DEditMode == 1;
				playerData.capsule[data.data.index].IsAppliedTemplate = data.data.isAppliedTemplate == 1;
				playerData.capsule[data.data.index].AffixSealCount = data.data.affixSealCount;
				playerData.capsule[data.data.index].AttachPokemonId = data.data.attachPokemonId;
				playerData.capsule[data.data.index].AttachPersonalRnd = data.data.attachPersonalRnd;
				_selectPokemon.SetPreparationIconReady(stationIndex);
				return;
			}

			if (_currentState != MatchingState.SelectBattleTeam)
				return;

			if (playerData.battleTeam == null)
				playerData.battleTeam = new PokemonParam[6];

			playerData.battleTeam[data.data.index] = pokemonParam;
			playerData.battleTeamNum = data.data.num;
			_selectBattleTeam.SetPreparationIconReady(stationIndex);
			return;
		}
	}
	private void ReceiveCancelPokemonData(global::Dpr.NetworkUtils.NetDataBattleMatchingCancelPokemon data) {
		int stationIndex = data.FromStationIndex;
		BattleMatchingPlayerData[] playerDataList = BattleMatchingWork.playerDataList;
		for (int i = 0; i < playerDataList.Length; i++)
		{
			BattleMatchingPlayerData playerData = playerDataList[i];
			if (playerData == null || playerData.stationIndex != stationIndex)
				continue;

			if (_currentState == MatchingState.SelectPokemon)
			{
				playerData.battlePokemonNum = 0;
				playerData.battlePokemon = null;
				playerData.capsule = null;
				return;
			}

			if (_currentState != MatchingState.SelectBattleTeam)
				return;

			playerData.battleTeam = null;
			playerData.battleTeamNum = 0;
			_selectBattleTeam.SetPreparationIconWait(stationIndex);
			return;
		}
	}
