	private void SetPlayReport() {
		uint result = (uint)BattleMatchingWork.battleResult;
		int monsNum = BattleMatchingWork.orderIndexList.Length;
		List<uint> monsNoList = new List<uint>();
		List<uint> monsFormList = new List<uint>();
		for (int i = 0; i < monsNum; i++)
		{
			PokemonParam param = BattleMatchingWork.pokemonParams[BattleMatchingWork.orderIndexList[i]];
			if (param != null)
			{
				monsNoList.Add((uint)param.GetMonsNo());
				monsFormList.Add(param.GetFormNo());
			}
		}

		int ruleId;
		switch (BattleMatchingWork.pokemonNum)
		{
			case PokemonNum.Num_3:
			case PokemonNum.Num_4:
				ruleId = 10000;
				break;
			case PokemonNum.Num_1_3:
			case PokemonNum.Num_1_6:
			case PokemonNum.Num_2_6:
				ruleId = 20000;
				break;
			default:
				ruleId = 30000;
				break;
		}

		switch (BattleMatchingWork.pokemonLevel)
		{
			case Dpr.Regulation.LevelRangeType.SAME:
				ruleId += 1000;
				break;
			case Dpr.Regulation.LevelRangeType.DRAG_DOWN:
				ruleId += 2000;
				break;
			case Dpr.Regulation.LevelRangeType.NONE:
				ruleId += 3000;
				break;
		}

		ruleId += BattleMatchingWork.isBanLegendPokemon ? 100 : 200;
		ruleId += BattleMatchingWork.isBanSamePokemon ? 10 : 20;
		ruleId += BattleMatchingWork.isBanSameItem ? 1 : 2;

		if (BattleMatchingWork.networkType == IlcaNetSessionNetworkType.Local)
		{
			if (!BattleMatchingWork.isColiseum)
			{
				switch (BattleMatchingWork.battleModeID)
				{
					case BattleModeID.Single:
						PlayReportManager.SaveReportLog_UnionBattleSingleP2P(result, (uint)ruleId, monsNoList.ToArray(), monsFormList.ToArray(), (uint)monsNum);
						break;
					case BattleModeID.Double:
						PlayReportManager.SaveReportLog_UnionBattleDoubleP2P(result, (uint)ruleId, monsNoList.ToArray(), monsFormList.ToArray(), (uint)monsNum);
						break;
					case BattleModeID.Mix:
						PlayReportManager.SaveReportLog_UnionBattleMultiP2P(result, (uint)ruleId, monsNoList.ToArray(), monsFormList.ToArray(), (uint)monsNum);
						break;
				}
			}
			else
			{
				switch (BattleMatchingWork.battleModeID)
				{
					case BattleModeID.Single:
						PlayReportManager.SaveReportLog_ColiseumBattleSingleP2P(result, (uint)ruleId, monsNoList.ToArray(), monsFormList.ToArray(), (uint)monsNum);
						break;
					case BattleModeID.Double:
						PlayReportManager.SaveReportLog_ColiseumBattleDoubleP2P(result, (uint)ruleId, monsNoList.ToArray(), monsFormList.ToArray(), (uint)monsNum);
						break;
					case BattleModeID.Multi:
						PlayReportManager.SaveReportLog_ColiseumBattleMultiP2P(result, (uint)ruleId, monsNoList.ToArray(), monsFormList.ToArray(), (uint)monsNum);
						break;
				}
			}
		}
		else
		{
			if (!BattleMatchingWork.isColiseum)
			{
				switch (BattleMatchingWork.battleModeID)
				{
					case BattleModeID.Single:
						PlayReportManager.SaveReportLog_UnionBattleSingleNet(result, (uint)ruleId, monsNoList.ToArray(), monsFormList.ToArray(), (uint)monsNum);
						break;
					case BattleModeID.Double:
						PlayReportManager.SaveReportLog_UnionBattleDoubleNet(result, (uint)ruleId, monsNoList.ToArray(), monsFormList.ToArray(), (uint)monsNum);
						break;
					case BattleModeID.Mix:
						PlayReportManager.SaveReportLog_UnionBattleMultiNet(result, (uint)ruleId, monsNoList.ToArray(), monsFormList.ToArray(), (uint)monsNum);
						break;
				}
			}
			else
			{
				switch (BattleMatchingWork.battleModeID)
				{
					case BattleModeID.Single:
						PlayReportManager.SaveReportLog_ColiseumBattleSingleNet(result, (uint)ruleId, monsNoList.ToArray(), monsFormList.ToArray(), (uint)monsNum);
						break;
					case BattleModeID.Double:
						PlayReportManager.SaveReportLog_ColiseumBattleDoubleNet(result, (uint)ruleId, monsNoList.ToArray(), monsFormList.ToArray(), (uint)monsNum);
						break;
					case BattleModeID.Multi:
						PlayReportManager.SaveReportLog_ColiseumBattleMultiNet(result, (uint)ruleId, monsNoList.ToArray(), monsFormList.ToArray(), (uint)monsNum);
						break;
				}
			}
		}
	}
	private void CheckReceivedPacket() {
		while (_loadingRecieveData.Count > 0)
		{
			INetData netData = _loadingRecieveData.Dequeue();
			BattleMatchingWork.EmitLog(string.Format("Find Receive Data on StartProcess : [{0}]", netData));
			ReceiveData(netData);
		}
	}
	public BattleMatchingManager() { }
